$c='using System; using System.Runtime.InteropServices; public class WO { [DllImport("user32.dll")] public static extern bool EnumWindows(EnumProc f, IntPtr l); [DllImport("user32.dll")] public static extern int GetWindowText(IntPtr h, System.Text.StringBuilder s, int n); [DllImport("user32.dll")] public static extern bool IsWindowVisible(IntPtr h); public delegate bool EnumProc(IntPtr h, IntPtr l); public static string Dialogs(){ string r="none"; EnumWindows((h,l)=>{ if(IsWindowVisible(h)){ var sb=new System.Text.StringBuilder(256); GetWindowText(h,sb,256); if(sb.ToString()=="Addictive Drums 2") r="DIALOG PRESENT"; } return true; },IntPtr.Zero); return r; } }'
Add-Type -TypeDefinition $c; [WO]::Dialogs()
